import{_ as i,l as o,o as e,c as s,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"VAR 尺度自回归","description":"","frontmatter":{"title":"VAR 尺度自回归","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/var-next-scale.md","filePath":"llm/var-next-scale.md","lastUpdated":1789023840000}'),_={name:"llm/var-next-scale.md"};function h(A,a,m,B,u,E){const l=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="var-尺度自回归" tabindex="-1">VAR 尺度自回归 <a class="header-anchor" href="#var-尺度自回归" aria-label="Permalink to &quot;VAR 尺度自回归&quot;">​</a></h1><div class="epigraph"><p>下一格是局部的。下一尺度是整张图从粗到细。把自回归定义在分辨率金字塔上，布局先于纹理。</p><footer>—— Tian 等 Visual Autoregressive Modeling（next-scale prediction）</footer></div><p><a href="/llm/autoregressive-image-gen">上一课</a>在 raster 码上逐步写格。缺口是分解顺序：人看图是先轮廓后细节，不是先左上角一个 patch。VAR 把 \\(p\\) 定义在多尺度 token 图上：先预测最低分辨率整图，再条件于它预测更高一层。后课 MAR 默认：仍可自回归，但不必须离散码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>raster AR 的因果掩码与二维邻域冲突，长程竖直依赖要绕一整行。多尺度向量量化（或残差尺度）给出 \\(r_1,r_2,\\ldots\\)：每层是该分辨率的完整离散图。Next-scale 预测整层，层内可并行（训练用双向或块掩码，推理按尺度步进）。这把「先布局后纹理」写进似然分解，而不是指望深层注意力自己学出来。</p><p>与理解侧原生分辨率不同：这里的多尺度是生成课程，不是阅读任意 \\(H\\times W\\)。</p><p><span class="marginnote">层内并行使训练吞吐高于纯 raster，但尺度数目、每层码本与上采样器都是新超参。尺度对不齐会棋盘或结构错位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构造尺度金字塔 tokenizer，按粗→细训练自回归（或块自回归）目标。采样必须从最粗层开始，不能随机从中层插入。验收看全局结构（对称、物体完整）是否优于同预算 raster，而不只是 FID 小数。</p>',9)),(e(),n(c,null,{default:r(()=>[p(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E7%B2%97%E5%B0%BA%E5%BA%A6%E6%95%B4%E5%9B%BE%22%5D%20--%3E%20S2%5B%22%E4%B8%8B%E4%B8%80%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E6%9B%B4%E7%BB%86%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20S3%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E5%83%8F%E7%B4%A0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>条件链是 \\(p(r_{k}\\mid r_{\\lt k})\\)。粗层错误会变成细层的错误布局，但粗层很短，布局被提前钉死，细层只补纹理。这与扩散从纯噪声同时出布局和纹理不同，也与 raster 把布局拖到序列中段不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>VAR 仍吃离散量化损失。下一课用掩码自回归在连续表示上生成，避开码本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VAR 用 next-scale 代替 next-token raster。</li><li>布局在短粗序列上先决定，纹理后补。</li><li>仍受离散 tokenizer 天花板约束。</li><li>出处：Tian 等 VAR。</li></ul>',6))])}const T=i(_,[["render",h]]);export{x as __pageData,T as default};
